from it_sci import H, nq, num, it

D = "A che cosa corrisponde questa descrizione: {v}?"


def f_misure(R):
    k = R.choice(["temp", "temp2", "massa", "vol", "lung"])
    if k == "temp":
        a, b = R.choice([(12, 20), (5, 18), (-3, 6), (15, 28), (8, 23), (20, 31), (-2, 9)])
        return nq("Al mattino il termometro segna %s °C, al pomeriggio %s °C. Di quanti gradi è salita la temperatura?" % (num(a, 3) if a >= 0 else "−%d" % -a, b), b - a,
                  [b + a, abs(a) + b + 2, b - a + 10, b], "°C", "Si fa la differenza: %d − (−%d) = %d °C." % (b, -a, b - a) if a < 0 else "Si fa la differenza: %d − %d = %d °C." % (b, a, b - a))
    if k == "temp2":
        a, b = R.choice([(25, 7), (18, 5), (30, 12), (22, 9), (16, 4), (35, 15)])
        return nq("Un bicchiere d’acqua è a %d °C. Messo in frigorifero si raffredda di %d gradi. Quanti gradi segna adesso?" % (a, b), a - b, [a + b, b, a - b - 10, a - b + 5], "°C",
                  "Si raffredda: %d − %d = %d °C." % (a, b, a - b))
    if k == "massa":
        a, b = R.choice([(350, 150), (500, 250), (1200, 800), (750, 250), (600, 400), (900, 350)])
        return nq("Sulla bilancia una scatola pesa %d g. Togliamo un oggetto di %d g. Quanto segna ora la bilancia?" % (a, b), a - b, [a + b, b, a - b + 100, a - b - 50], "g",
                  "%d − %d = %d g." % (a, b, a - b))
    if k == "vol":
        a, n = R.choice([(250, 4), (200, 5), (500, 3), (150, 6), (330, 3), (125, 8)])
        return nq("Versiamo %d bicchieri da %d ml in una brocca. Quanta acqua c’è nella brocca?" % (n, a), a * n, [a + n, a * (n - 1), a * n + a, a * n // 2], "ml",
                  "%d × %d = %d ml." % (n, a, a * n))
    a, b = R.choice([(45, 30), (120, 85), (75, 18), (60, 35), (150, 90), (98, 47)])
    return nq("Una pianta di fagiolo era alta %d mm. Dopo due settimane è alta %d mm. Di quanto è cresciuta?" % (b, a), a - b, [a + b, a, b, a - b + 10], "mm",
              "%d − %d = %d mm." % (a, b, a - b))


def f_calore(R):
    k = R.choice(["mix", "salita", "fusa", "bolle"])
    if k == "mix":
        a, b = R.choice([(20, 60), (10, 50), (30, 70), (40, 80), (16, 44), (24, 56), (12, 38), (18, 62), (26, 74)])
        return nq("Mescoliamo due bicchieri uguali di acqua: uno a %d °C e uno a %d °C. Che temperatura avrà più o meno l’acqua mescolata?" % (a, b), (a + b) / 2,
                  [a + b, b - a, b, a], "°C", "Con quantità uguali la temperatura finale sta a metà: (%d + %d) : 2 = %s °C." % (a, b, num((a + b) / 2)))
    if k == "salita":
        a, s, t = R.choice([(20, 5, 4), (15, 3, 5), (18, 6, 3), (22, 4, 6), (10, 8, 5), (25, 5, 5), (14, 7, 4), (30, 6, 5), (12, 9, 3)])
        return nq("Un pentolino d’acqua è a %d °C e si scalda di %d gradi ogni minuto. Che temperatura avrà dopo %d minuti?" % (a, s, t), a + s * t,
                  [a + s + t, s * t, a * s, a + s * t + 10], "°C", "%d + %d × %d = %d °C." % (a, s, t, a + s * t))
    if k == "fusa":
        return it("A quale temperatura fonde il ghiaccio?", "0 °C", ["100 °C", "10 °C", "−10 °C"], "Il ghiaccio fonde a 0 °C.")
    return it("A quale temperatura bolle l’acqua (al livello del mare)?", "100 °C", ["0 °C", "50 °C", "37 °C"], "L’acqua bolle a 100 °C.")


